steps.body:
An operator is just a function with a special name. Write `operator+` inside your type and `a + b` calls `a.operator+(b)`.

```cpp harness
#include <iostream>

struct Vec2 {
    int x;
    int y;

    {{code}}
};

int main() {
    const Vec2 a{3, 4};
    const Vec2 b{1, 2};
    const Vec2 sum = a + b;
    std::cout << '(' << sum.x << ", " << sum.y << ")\n";
    return 0;
}
```

```cpp
Vec2 operator+(const Vec2& other) const {
    return {x + other.x, y + other.y};
}
```

Take the right side by `const&` and mark the operator `const`, because `+` builds a new value and changes neither side. `operator-` looks the same. `operator+=` is different: it changes the left object, so it is not `const`, and it returns `*this` by reference (`Vec2&`). That avoids a copy and lets `a += b` behave like the built-in one.

A member operator always has your object on the **left**. `v * 2` can be a member, but `2 * v` cannot, because `int` has no members. Write it as a non-member function after the struct:

```cpp harness
#include <iostream>

struct Vec2 {
    int x;
    int y;
};

{{code}}

int main() {
    const Vec2 a{3, 4};
    const Vec2 twice = 2 * a;
    std::cout << '(' << twice.x << ", " << twice.y << ")\n";
    return 0;
}
```

```cpp
Vec2 operator*(int k, const Vec2& v) {
    return {k * v.x, k * v.y};
}
```

For equality, write `bool operator==(const Vec2& other) const`. C++17 does **not** generate `!=` from `==`, so `a != b` will not compile until you define `operator!=` too. Write it as `return !(*this == other);` so the two can never disagree.

Overload an operator only when its meaning is obvious. `+` on a money type is clear, `+` on a database connection is not.

example.code:
#include <iostream>

struct Vec2 {
    int x;
    int y;

    Vec2 operator+(const Vec2& other) const {
        return {x + other.x, y + other.y};
    }
    Vec2 operator-(const Vec2& other) const {
        return {x - other.x, y - other.y};
    }
    Vec2& operator+=(const Vec2& other) {
        x += other.x;
        y += other.y;
        return *this;
    }
    bool operator==(const Vec2& other) const {
        return x == other.x && y == other.y;
    }
    bool operator!=(const Vec2& other) const {
        return !(*this == other);
    }
    void print() const {
        std::cout << '(' << x << ", " << y << ")\n";
    }
};

Vec2 operator*(int k, const Vec2& v) {
    return {k * v.x, k * v.y};
}

int main() {
    const Vec2 a{3, 4};
    const Vec2 b{1, 2};
    (a + b).print();
    (a - b).print();
    (2 * a).print();

    Vec2 pos{0, 0};
    pos += a;
    pos += b;
    pos.print();

    std::cout << std::boolalpha;
    std::cout << (pos == a + b) << '\n';
    std::cout << (a != b) << '\n';
    return 0;
}

