steps.body:
To write `std::cout << date`, overload `operator<<`. The stream is on the left, so it must be a non-member. It takes the stream by reference, your object by `const&`, and returns the same stream:

```cpp harness
#include <iostream>

class Date {
public:
    Date(int year, int month, int day) : year_(year), month_(month), day_(day) {}

    friend std::ostream& operator<<(std::ostream& os, const Date& d);

private:
    int year_;
    int month_;
    int day_;
};

{{code}}

int main() {
    const Date start(2024, 3, 7);
    std::cout << start << '\n';
    return 0;
}
```

```cpp
std::ostream& operator<<(std::ostream& os, const Date& d) {
    os << d.year_ << '-' << d.month_;
    return os;
}
```

Returning `os` is what makes chaining work. `std::cout << a << " to " << b` runs as `(std::cout << a) << " to "`, so each call must hand the stream to the next.

A non-member cannot see private fields. Declare it a **friend** inside the class with `friend std::ostream& operator<<(std::ostream& os, const Date& d);`. A friend is not a member, it is a function the class trusts with its private data.

For zero padding, use `std::setw(2)` from `<iomanip>` with a fill of `'0'`. `os << std::setfill('0')` sets the fill, and `os.fill('0')` does the same but also returns the old fill character. The gotcha: `std::setfill` and `os.fill` are sticky, so a later `std::cout << std::setw(6) << 42` would print `000042`. Save the old fill and put it back:

```cpp harness
#include <iomanip>
#include <iostream>

class Date {
public:
    Date(int year, int month, int day) : year_(year), month_(month), day_(day) {}

    friend std::ostream& operator<<(std::ostream& os, const Date& d);

private:
    int year_;
    int month_;
    int day_;
};

std::ostream& operator<<(std::ostream& os, const Date& d) {
    os << d.year_ << '-';
    {{code}}
    return os;
}

int main() {
    const Date start(2024, 3, 7);
    std::cout << start << '\n';
    std::cout << std::setw(4) << 7 << '\n';
    return 0;
}
```

```cpp
const char oldFill = os.fill('0');  // set '0', remember the old one
os << std::setw(2) << d.month_;
os.fill(oldFill);                   // restore
```

`setw` only affects the next item, so it needs no cleanup.

example.code:
#include <iomanip>
#include <iostream>

class Date {
public:
    Date(int year, int month, int day) : year_(year), month_(month), day_(day) {}

    friend std::ostream& operator<<(std::ostream& os, const Date& d);

private:
    int year_;
    int month_;
    int day_;
};

std::ostream& operator<<(std::ostream& os, const Date& d) {
    const char oldFill = os.fill('0');
    os << d.year_ << '-' << std::setw(2) << d.month_ << '-' << std::setw(2) << d.day_;
    os.fill(oldFill);
    return os;
}

int main() {
    const Date start(2024, 3, 7);
    const Date end(2024, 12, 25);
    std::cout << start << " to " << end << '\n';
    std::cout << std::setw(4) << 7 << '\n';
    return 0;
}

