#include <iomanip>
#include <iostream>

class Time {
public:
    Time(int hours, int minutes) : hours_(hours), minutes_(minutes) {}

    Time plusOneHour() const {
        return Time((hours_ + 1) % 24, minutes_);
    }

    friend std::ostream& operator<<(std::ostream& os, const Time& t);

private:
    int hours_;
    int minutes_;
};

std::ostream& operator<<(std::ostream& os, const Time& t) {
    const char oldFill = os.fill('0');
    os << std::setw(2) << t.hours_ << ':' << std::setw(2) << t.minutes_;
    os.fill(oldFill);
    return os;
}

int main() {
    int hours = 0;
    int minutes = 0;
    std::cin >> hours >> minutes;
    const Time now(hours, minutes);
    std::cout << now << ' ' << now.plusOneHour() << '\n';
    std::cout << std::setw(3) << minutes << '\n';
    return 0;
}

steps.body:
Give your type `bool operator<(const Type& other) const` and the standard library knows how to order it. `std::sort(v.begin(), v.end())` uses `<` when you pass no comparator, and `std::set<T>` and `std::map<K, V>` keys need it too. Without it, those lines fail to compile with a long template error.

Comparing several fields by hand is easy to get wrong. `std::tie` from `<tuple>` packs references to fields into a tuple, and tuples compare field by field, left to right:

```cpp harness
#include <algorithm>
#include <iostream>
#include <tuple>
#include <vector>

struct Version {
    int major;
    int minor;
    int patch;

    {{code}}
};

int main() {
    std::vector<Version> versions = {{1, 10, 0}, {1, 2, 3}, {0, 9, 9}};
    std::sort(versions.begin(), versions.end());
    for (const Version& v : versions) {
        std::cout << v.major << '.' << v.minor << '.' << v.patch << '\n';
    }
    return 0;
}
```

```cpp
bool operator<(const Version& other) const {
    return std::tie(major, minor, patch) <
           std::tie(other.major, other.minor, other.patch);
}
```

`std::tie` makes no copies, it just refers to the fields. List them in priority order.

A set or map never calls `==`. It treats two keys as the same when neither is less than the other: `!(a < b) && !(b < a)`. So your `<` must compare every field that makes two objects different, or the set will silently drop values it thinks are duplicates.

Comparing as numbers matters: version `1.10.0` is newer than `1.2.3`, even though the string `"1.10.0"` sorts first.

example.code:
#include <algorithm>
#include <iostream>
#include <map>
#include <set>
#include <string>
#include <tuple>
#include <vector>

struct Version {
    int major;
    int minor;
    int patch;

    bool operator<(const Version& other) const {
        return std::tie(major, minor, patch) < std::tie(other.major, other.minor, other.patch);
    }
};

std::ostream& operator<<(std::ostream& os, const Version& v) {
    return os << v.major << '.' << v.minor << '.' << v.patch;
}

template <typename C>
void printLine(const C& items) {
    bool first = true;
    for (const auto& item : items) {
        if (!first) {
            std::cout << ' ';
        }
        std::cout << item;
        first = false;
    }
    std::cout << '\n';
}

int main() {
    std::vector<Version> versions = {{1, 10, 0}, {1, 2, 3}, {0, 9, 9}, {1, 2, 3}, {1, 2, 0}};
    std::sort(versions.begin(), versions.end());
    printLine(versions);

    const std::set<Version> distinct(versions.begin(), versions.end());
    std::cout << distinct.size() << " unique, newest " << *distinct.rbegin() << '\n';

    const std::map<Version, std::string> names = {{{1, 10, 0}, "Gold"}, {{0, 9, 9}, "Alpha"}, {{1, 2, 0}, "Beta"}};
    for (const auto& [version, name] : names) {
        std::cout << version << ' ' << name << '\n';
    }
    return 0;
}

