#include <algorithm>
#include <functional>
#include <iostream>
#include <set>
#include <vector>

struct ByLastDigit {
    bool operator()(int a, int b) const {
        if (a % 10 != b % 10) {
            return a % 10 < b % 10;
        }
        return a < b;
    }
};

template <typename C>
void printLine(const C& items) {
    bool first = true;
    for (const auto& item : items) {
        if (!first) {
            std::cout << ' ';
        }
        std::cout << item;
        first = false;
    }
    std::cout << '\n';
}

int main() {
    int n = 0;
    std::cin >> n;
    std::vector<int> nums(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> nums[i];
    }

    std::sort(nums.begin(), nums.end(), ByLastDigit{});
    printLine(nums);

    const std::set<int, ByLastDigit> distinct(nums.begin(), nums.end());
    printLine(distinct);

    std::set<int, std::greater<int>> digits;
    for (int x : nums) {
        digits.insert(x % 10);
    }
    printLine(digits);
    return 0;
}
